def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            components.append((color, cells))

    # Find the corner-L guide: two solid perpendicular arms of one color.
    guides = []
    for idx, (color, cells) in enumerate(components):
        if color == background:
            continue
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        height, width = r1 - r0 + 1, c1 - c0 + 1
        if height < 3 or width < 3 or len(cells) != height + width - 1:
            continue
        s = set(cells)
        for cr, vr in ((r0, 1), (r1, -1)):
            for cc, hc in ((c0, 1), (c1, -1)):
                shape = ({(cr, c) for c in range(c0, c1 + 1)}
                         | {(r, cc) for r in range(r0, r1 + 1)})
                if s == shape:
                    guides.append((len(cells), idx, color, cr, cc, vr, hc, height, width))
                    break
            else:
                continue
            break

    if not guides:
        return [row[:] for row in grid]

    _, guide_idx, guide_color, cr, cc, vertical_arm, horizontal_arm, height, width = max(guides)
    # The longer arm indicates one axis; the target is in the diagonal quadrant
    # along that arm and opposite the shorter arm.
    if width > height:
        row_direction = -vertical_arm
        col_direction = horizontal_arm
    elif height > width:
        row_direction = vertical_arm
        col_direction = -horizontal_arm
    else:
        return [row[:] for row in grid]

    candidates = []
    for idx, (color, cells) in enumerate(components):
        if idx == guide_idx or color == background:
            continue
        center_r = sum(r for r, _ in cells) / len(cells)
        center_c = sum(c for _, c in cells) / len(cells)
        if (center_r - cr) * row_direction > 0 and (center_c - cc) * col_direction > 0:
            candidates.append((len(cells), idx))

    if not candidates:
        return [row[:] for row in grid]
    _, target_idx = max(candidates)
    out = [row[:] for row in grid]
    for r, c in components[target_idx][1]:
        out[r][c] = guide_color
    return out


